// The TypeScript you write. ": string" etc. are type annotations;
// "age?" marks a property that may be left out.
function greet(user: { name: string; age?: number }): string {
  return `Hello, ${user.name}`;
}

greet({ name: "Ada" });
// "@ts-expect-error" tells the checker: the next line SHOULD be an error.
// @ts-expect-error -- 'nme' does not exist; did you mean 'name'?
greet({ nme: "Ada" });

