type Align = "left" | "center" | "right";
type Id = string | number;

function pad(text: string, width: number, how: Align = "left"): string {
  if (how === "left") return text.padEnd(width);
  if (how === "right") return text.padStart(width);
  const space = width - text.length;
  return " ".repeat(Math.floor(space / 2)) + text + " ".repeat(Math.ceil(space / 2));
}

function describe(id: Id): string {
  return `#${id.toString()}`;      // OK: both members have toString
