type Shape = { kind: "circle"; radius: number } | { kind: "rect"; w: number; h: number };

function format(value: string | number | Date | null): string {
  if (value === null) return "-";
  if (typeof value === "number") return value.toFixed(2);   // number
  if (value instanceof Date) return value.toISOString();     // Date
  return value.trim();                                       // string
}

function area(s: Shape): number {
  switch (s.kind) {
    case "circle": return Math.PI * s.radius ** 2;  // circle member
    case "rect": return s.w * s.h;                    // rect member
  }
}

function speak(pet: { bark(): string } | { meow(): string }): string {
  return "bark" in pet ? pet.bark() : pet.meow();
}

console.log(format(3.14159), format(" hi "), format(null), area({ kind: "rect", w: 2, h: 3 }));
console.log(speak({ meow: () => "meow" }));

function parsePort(raw: string): number {
  const data: unknown = JSON.parse(raw);         // don't trust it yet
  if (typeof data === "object" && data !== null && "port" in data &&
      typeof data.port === "number") {
    return data.port;                             // narrowed to number
  }
  throw new Error("invalid config");
}

type Status = "active" | "paused" | "closed";
function label(s: Status): string {
  switch (s) {
    case "active": return "Running";
    case "paused": return "On hold";
    case "closed": return "Done";
    default: {
      const unreachable: never = s;    // breaks if Status gains a member
      return unreachable;
    }
  }
}

try { parsePort("{}"); } catch (e) {             // e: unknown
  console.log(e instanceof Error ? e.message : String(e), label("paused"));
}

