interface Cat { kind: "cat"; meow(): string }
interface Dog { kind: "dog"; bark(): string }

function isCat(pet: Cat | Dog): pet is Cat {
  return pet.kind === "cat";
}

function assertIsDefined<T>(value: T, name: string): asserts value is NonNullable<T> {
  if (value === undefined || value === null) throw new Error(`${name} is missing`);
}

const pets: (Cat | Dog)[] = [
  { kind: "cat", meow: () => "meow" },
  { kind: "dog", bark: () => "woof" },
];

const cats = pets.filter(isCat);                         // Cat[]
console.log(cats.map(c => c.meow()));

const maybe = [1, undefined, 3].filter(n => n !== undefined); // number[] (TS 5.5+)

const config: { port?: string } = { port: "8080" };
const port = config.port;                                // string | undefined
assertIsDefined(port, "port");
console.log(port.padStart(5), maybe);                    // port: string

type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number }
  | { kind: "rect"; width: number; height: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.radius ** 2;
    case "square": return shape.side ** 2;
    case "rect": return shape.width * shape.height;
    default: {
      const unhandled: never = shape;   // compile error if a kind is missed
      throw new Error(`Unknown shape: ${JSON.stringify(unhandled)}`);
    }
  }
}

// <T> is a placeholder for any type (see Generics)
type Result<T> = { ok: true; value: T } | { ok: false; error: string };
function parseAge(input: string): Result<number> {
  const n = Number(input);
  return Number.isInteger(n) && n >= 0 ? { ok: true, value: n } : { ok: false, error: `bad age: ${input}` };
}
const r = parseAge("42");
console.log(r.ok ? r.value + 1 : r.error, area({ kind: "rect", width: 2, height: 5 }));

// <T> is a placeholder for any type (see Generics)
interface Repository<T> { find(id: string): T | undefined }

abstract class Entity {
  constructor(public readonly id: string) {}           // parameter property
  abstract describe(): string;
}

class User extends Entity {
  #loginCount = 0;                                      // runtime-private
  protected role: "admin" | "member" = "member";
  constructor(id: string, public name: string) { super(id); }

  login(): number { return ++this.#loginCount; }
  override describe(): string { return `${this.name} (${this.role})`; }
}

class MemoryRepo implements Repository<User> {
  private items = new Map<string, User>();
  add(user: User): void { this.items.set(user.id, user); }
  find(id: string): User | undefined { return this.items.get(id); }
}

const repo = new MemoryRepo();
repo.add(new User("u1", "Ada"));
console.log(repo.find("u1")?.describe());              // "Ada (member)"

function first<T>(items: readonly T[]): T | undefined {
  return items[0];
}

// K extends PropertyKey: K must be a valid key type (constraints: next lesson)
function groupBy<T, K extends PropertyKey>(items: T[], key: (item: T) => K): Record<K, T[]> {
  const out = {} as Record<K, T[]>;
  for (const item of items) {
    (out[key(item)] ??= []).push(item);
  }
  return out;
}
interface ApiResponse<T> { data: T; status: number }
type Pair<A, B = A> = [A, B];
const word = first(["a", "b"]);                     // string | undefined
const byLength = groupBy(["hi", "yo", "hey"], s => s.length);  // Record<number, string[]>
const res: ApiResponse<{ id: number }[]> = { data: [{ id: 1 }], status: 200 };
const range: Pair<number> = [0, 10];
class Stack<T> {
  #items: T[] = [];
  push(item: T): void { this.#items.push(item); }
  pop(): T | undefined { return this.#items.pop(); }
}
const s = new Stack<string>();
s.push("x");
console.log(word, byLength[3], res.data[0]?.id, range, s.pop());

function longest<T extends { length: number }>(a: T, b: T): T {
  return a.length >= b.length ? a : b;
}

function prop<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

interface Paginated<T = string> { items: T[]; next?: string }

function pickColor<C extends string>(colors: C[], fallback: NoInfer<C>): C {
  return colors[0] ?? fallback;
}

const user = { name: "Ada", age: 36 };
const longer = longest("abc", "de");        // string
const age = prop(user, "age");              // number
const page: Paginated = { items: ["a"] };   // T defaults to string
const c = pickColor(["red", "blue"], "red"); // "red" | "blue"

// @ts-expect-error -- "nmae" is not assignable to "name" | "age"
prop(user, "nmae");
// @ts-expect-error -- "green" not in "red" | "blue" thanks to NoInfer
pickColor(["red", "blue"], "green");
console.log(longer, age, page.items, c);

interface User {
  id: number;
  name: string;
  email: string;
  role: "admin" | "member" | "guest";
  createdAt: Date;
}

type NewUser = Omit<User, "id" | "createdAt">;
type UserPatch = Partial<NewUser>;
type PublicUser = Pick<User, "id" | "name">;
type Staff = Exclude<User["role"], "guest">;            // "admin" | "member"
type Labels = Record<User["role"], string>;

async function loadUser(id: number): Promise<PublicUser> {
  return { id, name: "Ada" };
}
type Loaded = Awaited<ReturnType<typeof loadUser>>;     // PublicUser
type LoadArgs = Parameters<typeof loadUser>;            // [id: number]

const patch: UserPatch = { email: "ada@example.com" };
const labels: Labels = { admin: "Admin", member: "Member", guest: "Guest" };
const role: Staff = "member";
const args: LoadArgs = [1];
loadUser(...args).then((u: Loaded) => console.log(u.name, patch, labels[role]));

interface User { id: number; name: string }

function isUser(x: unknown): x is User {
  return typeof x === "object" && x !== null &&
    "id" in x && typeof x.id === "number" &&
    "name" in x && typeof x.name === "string";
}

async function fetchUser(id: number): Promise<User> {
  const res = await fetch(`https://api.example.com/users/${id}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const body: unknown = await res.json();       // don't trust `any`
  if (!isUser(body)) throw new Error("Unexpected response shape");
  return body;
}

async function main(): Promise<void> {
  try {
    const [a, b] = await Promise.all([fetchUser(1), fetchUser(2)]); // [User, User]
    console.log(a.name, b.name);
  } catch (e) {                                  // e: unknown
    console.error(e instanceof Error ? e.message : String(e));
  }
}
main();

