// count-any.ts: report every exported function whose return type is `any`
import ts from "typescript";

const program = ts.createProgram(["src/index.ts"], { strict: true, noEmit: true });
const checker = program.getTypeChecker();

for (const file of program.getSourceFiles()) {
  if (file.isDeclarationFile) continue;
  const visit = (node: ts.Node): void => {
    if (ts.isFunctionDeclaration(node) && node.name) {
      const signature = checker.getSignatureFromDeclaration(node);
      const returns = signature && checker.getReturnTypeOfSignature(signature);
      if (returns && returns.flags & ts.TypeFlags.Any) {
        const { line } = file.getLineAndCharacterOfPosition(node.getStart());
        console.log(`${file.fileName}:${line + 1} ${node.name.text} returns any`);
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(file);
}

const errors = ts.getPreEmitDiagnostics(program);
console.log(`${errors.length} diagnostics`);
